<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only.');}
$source=$argv[1]??'';if(!is_file($source)){fwrite(STDERR,"Usage: php database/restore.php backup.sqlite\nStop Apache / the website first.\n");exit(1);}
try{$check=new PDO('sqlite:'.$source);$check->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);if($check->query('PRAGMA integrity_check')->fetchColumn()!=='ok')throw new RuntimeException('Database integrity check failed.');$required=['users','customers','reservations','venues','packages','products','suppliers','movements','purchases','sales','payments','employees','assignments','audit','settings','login_attempts'];$tables=$check->query("SELECT name FROM sqlite_master WHERE type='table'")->fetchAll(PDO::FETCH_COLUMN);if(array_diff($required,$tables))throw new RuntimeException('Backup is missing required tables.');$check=null;$target=getenv('UNCORKED_DB_PATH') ?: dirname(__DIR__).'/storage/uncorked.sqlite';$staged=dirname($target).'/restore-staged-'.bin2hex(random_bytes(4)).'.sqlite';if(!copy($source,$staged))throw new RuntimeException('Could not stage backup.');if(is_file($target)&&!copy($target,$target.'.before-restore-'.date('Ymd-His').'.bak'))throw new RuntimeException('Could not create safety copy.');if(!rename($staged,$target))throw new RuntimeException('Could not replace database. Ensure the site is stopped.');echo "Restore completed. A safety copy of the previous database was retained.\n";}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
